private val LightColors = lightColorScheme(primary = RouteBlue, onPrimary = Color.White, primaryContainer = RouteBlueSoft, onPrimaryContainer = RouteNavy, secondary = RouteGreen, secondaryContainer = RouteMint, onSecondaryContainer = Color(0xFF06452C), background = RouteCanvas, surface = Color.White, surfaceVariant = Color(0xFFEFF3F8), outline = Color(0xFFD6DEE8), error = Color(0xFFB3261E))
private val DarkColors = darkColorScheme(primary = Color(0xFF9CC3FF), onPrimary = Color(0xFF00315F), primaryContainer = Color(0xFF124C8B), onPrimaryContainer = Color.White, secondary = Color(0xFF8BDDB5), background = Color(0xFF0E141B), surface = Color(0xFF161D25), surfaceVariant = Color(0xFF27313C))

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContent { ContextRouteApp() } }
}

@Composable fun ContextRouteApp(vm: AppViewModel = viewModel()) {
    val base = MaterialTheme.typography
    val type = if (vm.largeText) base.copy(bodyLarge = base.bodyLarge.copy(fontSize = 18.sp), bodyMedium = base.bodyMedium.copy(fontSize = 16.sp), labelLarge = base.labelLarge.copy(fontSize = 16.sp)) else base
    MaterialTheme(colorScheme = if (vm.darkMode) DarkColors else LightColors, typography = type) { Surface(Modifier.fillMaxSize(), color = MaterialTheme.colorScheme.background) { ScreenHost(vm) } }
}

@Composable private fun ScreenHost(vm: AppViewModel) {
    val immersive = vm.route in listOf("splash", "onboard1", "onboard2", "onboard3", "permission", "navigation", "emergency")
    Scaffold(bottomBar = { if (!immersive) BottomBar(vm) }, containerColor = MaterialTheme.colorScheme.background) { pad -> Box(Modifier.padding(pad)) { when (vm.route) {
        "splash" -> Splash(vm); "onboard1" -> Onboard(vm, 1, "Smarter routes", "Recommendations that adapt to your purpose, preferences and the road ahead.", Icons.Default.Route)
        "onboard2" -> Onboard(vm, 2, "Your journey, your context", "Choose family, work, tourism, medical or religious travel and get a route that fits.", Icons.Default.Explore)
        "onboard3" -> Onboard(vm, 3, "Safety and accessibility first", "See road conditions, hazards and accessible choices before you start moving.", Icons.Default.Shield)
        "permission" -> PermissionScreen(vm); "home" -> Home(vm); "search" -> Search(vm); "context" -> ContextScreen(vm); "requirements" -> Requirements(vm)
        "routes" -> Routes(vm); "overview" -> Overview(vm); "navigation" -> NavigationScreen(vm); "explore" -> Explore(vm); "report" -> ReportForm(vm); "reportDetails" -> ReportDetails(vm); "lifecycle" -> Lifecycle(vm)
        "emergency" -> Emergency(vm); "saved" -> Saved(vm); "profile" -> Profile(vm); "offline" -> Offline(vm); "privacy" -> Privacy(vm); "settings" -> Settings(vm)
        else -> Home(vm)
    } } }
}

@Composable private fun BottomBar(vm: AppViewModel) { NavigationBar(containerColor = MaterialTheme.colorScheme.surface, tonalElevation = 8.dp) { listOf("home" to Icons.Default.Home, "explore" to Icons.Default.Explore, "saved" to Icons.Default.Bookmark, "profile" to Icons.Default.Person).forEach { (r, icon) -> NavigationBarItem(selected = vm.route == r, onClick = { vm.go(r) }, icon = { Icon(icon, null) }, label = { Text(r.replaceFirstChar { it.uppercase() }) }) } } }

@Composable private fun Header(title: String, vm: AppViewModel, subtitle: String? = null, back: Boolean = true, action: (@Composable () -> Unit)? = null) {
    Row(Modifier.fillMaxWidth().padding(horizontal = 20.dp, vertical = 16.dp), verticalAlignment = Alignment.CenterVertically) {
        if (back) IconButton({ vm.go("home") }, Modifier.semantics { contentDescription = "Go back" }) { Icon(Icons.Default.ArrowBack, "Back") }
        Column(Modifier.weight(1f)) { Text(title, style = MaterialTheme.typography.titleLarge, fontWeight = FontWeight.Bold); subtitle?.let { Text(it, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) } }
        action?.invoke()
    }
}

@Composable private fun Page(title: String, vm: AppViewModel, subtitle: String? = null, body: @Composable ColumnScope.() -> Unit) { LazyColumn(Modifier.fillMaxSize(), contentPadding = PaddingValues(bottom = 30.dp)) { item { Header(title, vm, subtitle) }; item { Column(Modifier.padding(horizontal = 20.dp), content = body) } } }
