@Composable private fun PermissionScreen(vm: AppViewModel) { val launcher = rememberLauncherForActivityResult(ActivityResultContracts.RequestMultiplePermissions()) { vm.go("home") }; Page("Set up your permissions", vm, "You stay in control") { Text("ContextRoute works best with a few optional Android permissions.", style = MaterialTheme.typography.bodyLarge); listOf(Triple("Location", "Show your position and find nearby facilities", Icons.Default.MyLocation), Triple("Notifications", "Keep you informed about saved trip updates", Icons.Default.Notifications), Triple("Camera / photos", "Attach an image to a road report", Icons.Default.CameraAlt)).forEach { (title, detail, icon) -> CardBox { Row(verticalAlignment = Alignment.CenterVertically) { Icon(icon, null, tint = RouteBlue); Spacer(Modifier.width(14.dp)); Column { Text(title, fontWeight = FontWeight.Bold); Text(detail, style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant) } } } }; Spacer(Modifier.height(12.dp)); Primary("Continue", { launcher.launch(arrayOf(Manifest.permission.ACCESS_FINE_LOCATION, Manifest.permission.ACCESS_COARSE_LOCATION, Manifest.permission.POST_NOTIFICATIONS)) }); TextButton({ vm.go("home") }, Modifier.fillMaxWidth()) { Text("Not now") }; Text("You can change permissions later in Android Settings. Denied permissions are never presented as granted.", color = MaterialTheme.colorScheme.onSurfaceVariant, style = MaterialTheme.typography.bodySmall) } }

