@Composable private fun ReportDetails(vm: AppViewModel) { Page("Report details", vm, "CR-${vm.report?.category?.take(2)?.uppercase() ?: "DE"}-001") { val r = vm.report ?: vm.reportDraft; StatusBanner("Local demo report · not verified by a server"); CardBox { Text("${r.category} · ${r.severity}", fontWeight = FontWeight.Bold, fontSize = 20.sp); Text(r.description.ifBlank { "No description provided" }, modifier = Modifier.padding(vertical = 10.dp)); Text("Source: user submitted", style = MaterialTheme.typography.bodySmall, color = MaterialTheme.colorScheme.onSurfaceVariant); Text("Status: ${r.status}", color = RouteBlue, fontWeight = FontWeight.Bold, modifier = Modifier.padding(top = 8.dp)) }; Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(8.dp)) { OutlinedButton({ }, Modifier.weight(1f), shape = RoundedCornerShape(14.dp)) { Text("Helpful") }; OutlinedButton({ }, Modifier.weight(1f), shape = RoundedCornerShape(14.dp)) { Text("Share") } }; Primary("View lifecycle", { vm.go("lifecycle") }) } }
@Composable private fun Lifecycle(vm: AppViewModel) { Page("Report lifecycle", vm, "CR-${vm.report?.category?.take(2)?.uppercase() ?: "DE"}-001") { StatusBanner("Simulated lifecycle until backend verification exists"); listOf("Submitted" to "Just now", "Under Review" to "Pending review", "Verified" to "Not yet available").forEach { (a, b) -> CardBox { Row(verticalAlignment = Alignment.CenterVertically) { Icon(if (a == "Submitted") Icons.Default.CheckCircle else Icons.Default.Schedule, null, tint = if (a == "Submitted") RouteGreen else MaterialTheme.colorScheme.onSurfaceVariant); Spacer(Modifier.width(12.dp)); Column { Text(a, fontWeight = FontWeight.Bold); Text(b, color = MaterialTheme.colorScheme.onSurfaceVariant, style = MaterialTheme.typography.bodySmall) } } } } } }

