@Composable private fun Saved(vm: AppViewModel) { Page("Saved places", vm, "Your shortcuts") { if (vm.savedPlaces.isEmpty()) CardBox { Text("No saved places", fontWeight = FontWeight.Bold); Text("Add Home, Office or a custom place for faster planning.", color = MaterialTheme.colorScheme.onSurfaceVariant) }; vm.savedPlaces.forEach { place -> CardBox { Row(verticalAlignment = Alignment.CenterVertically) { Box(Modifier.size(40.dp).clip(CircleShape).background(RouteBlueSoft), contentAlignment = Alignment.Center) { Icon(Icons.Default.Bookmark, null, tint = RouteBlue) }; Spacer(Modifier.width(12.dp)); Text(place, Modifier.weight(1f), fontWeight = FontWeight.SemiBold); IconButton({ vm.savedPlaces.remove(place) }) { Icon(Icons.Default.DeleteOutline, "Delete saved place") } } } }; Primary("Add demo place", { vm.savedPlaces.add("Custom place · Added locally") }, icon = Icons.Default.Add) } }
